-- Issue #91, lot F : courses aux libertés (semeai), coupes et connexions, 9 × 9, Noir au trait.
-- Problèmes communs (owner_id null), tous prouvés par src/go/lot-f.test.ts. Aucun seki, aucun ko.
-- Insertion seule : aucun problème existant n'est modifié ni supprimé.
-- setup.refutation : texte affiché après une erreur.
-- La table puzzles garde sa RLS (activée dans 20260926235308_progression_problemes_lecons_badges).
insert into public.puzzles (id, owner_id, size, setup, answers, title, prompt, explanation, difficulty) values
 ('f01', null, 9, '{"rows":[".........",".........","..OX.....",".OSOX....","..SOX....","..O.X....",".........",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Tes pierres marquées n''ont qu''une liberté, B5 : Blanc y joue et les capture. Regarde aussi les pierres blanches qui les touchent : elles sont en atari, elles aussi."}', array['D4','B5'], 'Sauve tes pierres de coupe', 'Tes deux pierres marquées coupent Blanc, mais elles sont en atari. Sauve-les.', 'Bravo ! Tes pierres marquées sont des pierres de coupe : elles séparent les pierres blanches. Elles sont en atari (une seule liberté, B5), mais les deux pierres blanches D6-D5 aussi : leur seule liberté est D4. En D4, tu les captures, et tes pierres retrouvent des libertés. B5 marche aussi : tes pierres ont alors deux libertés, et si Blanc les attaque, tu prends D6-D5 en D4.', 700),
 ('f02', null, 9, '{"rows":[".........",".........",".........",".........","....X....",".OO......","...XX....","XO.T.X...",".XXOX...."],"toPlay":"B","refutation":"Pas tout à fait. Après E2, Blanc s''allonge en C2 : il se relie à sa pierre B2 et met en plus tes pierres B1-C1 en atari. Mets-le en atari de l''autre côté."}', array['C2'], 'Le bon côté', 'Noir joue et capture les pierres blanches marquées. Elles ont deux libertés : laquelle prendre ?', 'Bien vu ! C2 coupe les pierres marquées de la pierre blanche B2 et les met en atari (une seule liberté). Leur dernière liberté, E2, est entourée par tes pierres E3, F2 et E1 : Blanc ne peut pas s''y allonger, ce serait un suicide. En plus, C2 relie tes pierres B1-C1 et met B2 en atari.', 750),
 ('f03', null, 9, '{"rows":["..XT.OO..","..XTXO...","..X.X....","...X.....",".........",".........",".........",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Après ce coup, Blanc joue E9 et relie ses pierres marquées à son groupe de droite : elles sont sauvées. Coupe au point de liaison."}', array['E9'], 'Coupe au bord', 'Noir joue et capture les deux pierres blanches marquées. Elles ont deux libertés : E9 et D7.', 'Bravo ! E9 coupe les pierres marquées du groupe blanc de droite : couper, c''est jouer entre deux groupes adverses pour les séparer. Il leur reste une liberté, D7, entourée par tes pierres C7, E7 et D6 : Blanc ne peut pas s''y allonger, ce serait un suicide. Tu les captures au coup suivant.', 780),
 ('f04', null, 9, '{"rows":[".XO......","XXO......",".XO......","XXO......","X.OOO....","XTX.O....","XOX.O....",".OX.O....",".OXOO...."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue B5 et relie son groupe au mur blanc C5 : il sort de la course aux libertés et ne peut plus être capturé."}', array['B5'], 'Trois contre trois, une sortie', 'Course aux libertés : ton groupe C1-C4 et le groupe blanc marqué ont chacun 3 libertés. Joue le coup qui gagne.', 'Exact ! Dans une course aux libertés (semeai), deux groupes s''entourent et le premier qui prend toutes les libertés de l''autre gagne. Blanc a 3 libertés : A2, A1 et B5. Toi aussi : D4, D3 et D2. Mais en B5, Blanc se relierait au mur blanc C5. Bloque cette sortie d''abord : Blanc n''a plus que 2 libertés contre 3 pour toi, et tu le captures un coup avant lui.', 800),
 ('f05', null, 9, '{"rows":[".XO......","XXO......",".XO......","XXO......","X.OO.....","XTX.O....",".OX......",".OX......",".OX......"],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue B5 et relie son groupe au mur blanc C5 : il sort de la course et ne peut plus être capturé. Bloque d''abord la sortie."}', array['B5'], 'Bloque la sortie', 'Course aux libertés : ton groupe C1-C4 contre le groupe blanc marqué. Attention, Blanc peut rejoindre son mur.', 'Bravo ! Le groupe blanc a 4 libertés : A3, A2, A1 et B5. Mais B5 n''est pas une liberté comme les autres : en y jouant, Blanc se relierait au mur blanc C5. Dans une course aux libertés (semeai), où deux groupes s''entourent et où le premier qui prend toutes les libertés de l''autre gagne, on bloque d''abord la sortie. Après B5, Blanc a 3 libertés et toi 4 (D4, D3, D2, D1) : tu gagnes la course.', 900)
on conflict (id) do nothing;
